mapper.select:
SELECT  FROM prd_design
WHERE workspace_id = #{workspaceId} AND workitem_id = #{workitemId}
LIMIT 1

mapper.update:
UPDATE prd_design
SET target_repo_id = #{targetRepoId}, target_profile_id = NULL,
    target_app_root = #{targetAppRoot}, target_commit_sha = NULL,
    target_config_json = #{targetConfigJson}, version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id} AND workspace_id = #{workspaceId} AND version = #{expectedVersion}

UPDATE prd_design
SET delivery_mode = #{deliveryMode},
    version = version + 1
    , modifier_id = #{modifierId}
WHERE id = #{id} AND workspace_id = #{workspaceId} AND version = #{expectedVersion}

UPDATE prd_design
SET content_language = #{contentLanguage},
    version = version + 1
    , modifier_id = #{modifierId}
WHERE id = #{id} AND workspace_id = #{workspaceId} AND version = #{expectedVersion}

UPDATE prd_design
SET confirmed_version_id = #{confirmedVersionId},
    version = version + 1
    , modifier_id = #{modifierId}
WHERE id = #{id} AND workspace_id = #{workspaceId} AND version = #{expectedVersion}
